from collections import deque
class RateLimiter:
    def __init__(self, max_calls, period_seconds):
        self.max_calls = max_calls
        self.period = period_seconds
        self.calls = deque()
    def allow(self, timestamp):
        while self.calls and self.calls[0] <= timestamp - self.period:
            self.calls.popleft()
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

class KVStore:
    def __init__(self):
        self.store = {}
    def set(self, key, value, ttl, now):
        self.store[key] = (value, now + ttl)
    def get(self, key, now):
        if key not in self.store: return None
        value, expiry = self.store[key]
        if now >= expiry:
            del self.store[key]
            return None
        return value

from collections import Counter
def least_interval(tasks, n):
    counts = sorted(Counter(tasks).values(), reverse=True)
    max_count = counts[0]
    max_count_tasks = counts.count(max_count)
    return max(len(tasks), (max_count - 1) * (n + 1) + max_count_tasks)

